1	import { db } from "../lib/db";
2	import { debitWallet, InsufficientBalanceError } from "../lib/wallet";
3	import { invoiceCreateData } from "../lib/invoices";
4	import { markPromoRenewed } from "../lib/promo-redemption";
5	import { annualDiscountPct } from "../lib/annual-discount";
6	import { extraDiskCentsAt } from "../lib/extra-disk";
7	import { extraDiskPerGbCents } from "../lib/disk-expand";
8	import { walletSplit } from "../lib/wallet-split";
9	import {
10	  hasChargeableCard,
11	  chargeSavedCardOffSession,
12	  creditOffSessionCharge,
13	  cardDisplayLabel,
14	  renewalChargeMarker,
15	} from "../lib/stripe-cards";
16	import {
17	  PRODUCT_GRACE_DAYS,
18	  PRODUCT_WARN_DAYS,
19	  VOLUME_TERM_MONTHS,
20	  canAfford,
21	  dedupeSince,
22	  emailMonthlyBaseCents,
23	  frozenProductAnnualPct,
24	  graceEndsAt,
25	  money,
26	  needsUpcomingWarning,
27	  nextExpiry,
28	  productTermRenewalCents,
29	  reclaimAt,
30	  renewalDecision,
31	  subscriptionTermMonths,
32	  volumeRenewalCents,
33	  ymd,
34	} from "../lib/product-billing";
35	
36	/**
37	 * Recurring billing for the add-on products: business email subscriptions and
38	 * block-storage volumes. Until this existed only the *first* period was charged
39	 * at order time and nothing ever renewed — every one of these products was
40	 * silently free after month one.
41	 *
42	 * Policy (mirrors worker/billing.ts so the whole account behaves the same):
43	 *   T-3d   warn the owner if the renewal would fail (no funds / auto-renew off)
44	 *   T+0    charge the wallet, push `expiresAt` forward one term
45	 *   T+0..G still unpaid: keep it running, nag once per dedupe window
46	 *   T+G    enforce — email: status SUSPENDED (mailboxes kept)
47	 *                    volume: DETACHED + VOLUME_DETACH job (data kept)
48	 * Nothing here ever deletes customer data.
49	 *
50	 * The orchestrator (worker/index.ts) calls `productRenewalSweep()` on a timer.
51	 * Every step is individually try/caught so one poisoned row can never abort the
52	 * sweep, and every mutation is a conditional compare-and-swap so a re-run — or
53	 * two workers racing — can never double-charge.
54	 */
55	
56	const LOG = "[product-billing]";
57	
58	/** Thrown inside a renewal transaction when another sweep already handled the row. */
59	class AlreadyHandledError extends Error {
60	  constructor(what: string) {
61	    super(`already handled: ${what}`);
62	    this.name = "AlreadyHandledError";
63	  }
64	}
65	
66	/** Run a sweep phase, swallowing (but logging) any failure so the rest proceeds. */
67	async function phase(name: string, fn: () => Promise<void>): Promise<void> {
68	  try {
69	    await fn();
70	  } catch (e) {
71	    console.error(`${LOG} phase "${name}" failed`, e);
72	  }
73	}
74	
75	/** Run a per-row step; a bad row is logged and skipped, never fatal. */
76	async function step(what: string, fn: () => Promise<void>): Promise<void> {
77	  try {
78	    await fn();
79	  } catch (e) {
80	    console.error(`${LOG} ${what} failed`, e);
81	  }
82	}
83	
84	/** Best-effort notification (a notify failure must never roll back a charge). */
85	async function notify(userId: string, title: string, body?: string, href?: string) {
86	  try {
87	    await db.notification.create({ data: { userId, title, body, href } });
88	  } catch (e) {
89	    console.error(`${LOG} notify failed`, e);
90	  }
91	}
92	
93	/**
94	 * Send a notification at most once per dedupe window, keyed on the entity label
95	 * plus a stable marker phrase in the title (same technique as worker/billing.ts).
96	 */
97	async function notifyOnce(
98	  now: Date,
99	  userId: string,
100	  label: string,
101	  marker: string,
102	  title: string,
103	  body: string,
104	  href: string
105	) {
106	  const already = await db.notification.findFirst({
107	    where: {
108	      userId,
109	      createdAt: { gt: dedupeSince(now) },
110	      AND: [{ title: { contains: label } }, { title: { contains: marker } }],
111	    },
112	    select: { id: true },
113	  });
114	  if (already) return;
115	  await notify(userId, title, body, href);
116	}
117	
118	// ---------------------------------------------------------------------------
119	// Term-aware renewal pricing (shared by email + hosting)
120	//
121	// Both products now carry a per-subscription billing term (1 = monthly, 12 =
122	// annual) and a frozen annual discount, so a renewal is priced through the SAME
123	// `termPriceCents` formula the order charged — displayed === charged === renewed.
124	// The frozen rate WINS; `liveAnnual` (resolved once per sweep) is only the
125	// fallback for rows that predate the column, and for a monthly term the formula
126	// collapses to the plain monthly price so no existing row moves.
127	// ---------------------------------------------------------------------------
128	
129	/** Per-term renewal price of an email subscription (frozen annual rate wins). */
130	function emailRenewalPrice(
131	  sub: { termMonths?: number | null; annualDiscountPct?: number | null; emailPlan: { priceCents: number; termMonths?: number | null } },
132	  liveAnnual: number,
133	): number {
134	  const months = subscriptionTermMonths(sub);
135	  const annual = frozenProductAnnualPct(sub) ?? liveAnnual;
136	  return productTermRenewalCents(emailMonthlyBaseCents(sub.emailPlan), months, annual);
137	}
138	
139	/** Per-term renewal price of a hosting account (frozen annual rate wins). Adds any
140	 *  purchased extra storage — billed every cycle at the current $/GB/mo, same as the
141	 *  VPS add-on — so a customer who bought storage keeps paying for it each renewal. */
142	function hostingRenewalPrice(
143	  acct: { termMonths?: number | null; annualDiscountPct?: number | null; extraDiskGB?: number | null; plan: { priceCents: number } },
144	  liveAnnual: number,
145	  perGbCents: number,
146	): number {
147	  const months = subscriptionTermMonths(acct);
148	  const annual = frozenProductAnnualPct(acct) ?? liveAnnual;
149	  return productTermRenewalCents(acct.plan.priceCents, months, annual) + extraDiskCentsAt(acct.extraDiskGB ?? 0, perGbCents) * months;
150	}
151	
152	// ---------------------------------------------------------------------------
153	// Business email subscriptions
154	// ---------------------------------------------------------------------------
155	
156	const EMAIL_HREF = "/dashboard/email";
157	
158	/** Heads-up for subscriptions expiring soon whose renewal would fail today. */
159	async function emailUpcomingWarnings(now: Date) {
160	  const soon = new Date(now.getTime() + PRODUCT_WARN_DAYS * 86400_000);
161	  const upcoming = await db.emailSubscription.findMany({
162	    where: { status: "ACTIVE", expiresAt: { gt: now, lt: soon } },
163	    include: { emailPlan: true, user: true },
164	  });
165	  // Live annual rate, resolved once for the sweep as the fallback for any row that
166	  // predates the frozen column (frozen wins when present — see emailRenewalPrice).
167	  const liveAnnual = await annualDiscountPct();
168	
169	  for (const sub of upcoming) {
170	    await step(`email warn ${sub.id}`, async () => {
171	      const priceCents = emailRenewalPrice(sub, liveAnnual);
172	      if (!needsUpcomingWarning({ autoRenew: sub.autoRenew, balanceCents: sub.user.balanceCents, priceCents })) {
173	        return;
174	      }
175	      await notifyOnce(
176	        now,
177	        sub.userId,
178	        sub.domainName,
179	        "email renews soon",
180	        `${sub.domainName} email renews soon — action needed`,
181	        sub.autoRenew
182	          ? `Renewal is ${money(priceCents)} but your balance is ${money(sub.user.balanceCents)}. Top up before ${ymd(sub.expiresAt!)} to keep your mailboxes delivering.`
183	          : `Auto-renew is off. Renew manually before ${ymd(sub.expiresAt!)} to avoid suspension.`,
184	        EMAIL_HREF
185	      );
186	    });
187	  }
188	}
189	
190	/**
191	 * Charge + extend one subscription atomically.
192	 *
193	 * The compare-and-swap on `expiresAt` is the double-charge guard: the update
194	 * only matches while the row still carries the *old* expiry we based the
195	 * decision on, so a concurrent (or repeated) sweep matches zero rows, throws,
196	 * and rolls the whole transaction — wallet debit included — back.
197	 * Returns true when this call is the one that actually renewed.
198	 */
199	async function chargeEmailRenewal(
200	  sub: { id: string; userId: string; domainName: string; expiresAt: Date | null },
201	  planName: string,
202	  priceCents: number,
203	  newExpiry: Date
204	): Promise<boolean> {
205	  try {
206	    await db.$transaction(async (tx) => {
207	      const advanced = await tx.emailSubscription.updateMany({
208	        where: { id: sub.id, status: "ACTIVE", expiresAt: sub.expiresAt },
209	        data: { expiresAt: newExpiry },
210	      });
211	      if (advanced.count === 0) throw new AlreadyHandledError(`email ${sub.id}`);
212	
213	      if (priceCents > 0) {
214	        await debitWallet(tx, sub.userId, priceCents);
215	        await tx.walletTransaction.create({
216	          data: {
217	            userId: sub.userId,
218	            amountCents: -priceCents,
219	            description: `Business Email renewal: ${planName} for ${sub.domainName}`,
220	          },
221	        });
222	        // PAID invoice, inside the CAS-guarded tx — a repeated sweep matches zero
223	        // rows, throws AlreadyHandledError, and rolls this invoice back too.
224	        await tx.invoice.create({
225	          data: invoiceCreateData({
226	            userId: sub.userId,
227	            description: `Business Email renewal: ${planName} for ${sub.domainName}`,
228	            status: "PAID",
229	            period: { start: sub.expiresAt, end: newExpiry },
230	            lineItems: [
231	              { description: `${planName} — ${sub.domainName}`, qty: 1, unitCents: priceCents, amountCents: priceCents },
232	            ],
233	          }),
234	        });
235	      }
236	      await tx.auditLog.create({
237	        data: {
238	          userId: sub.userId,
239	          action: "billing.renewed",
240	          detail: `email ${sub.id} ${sub.domainName} ${money(priceCents)} -> ${ymd(newExpiry)}`,
241	        },
242	      });
243	      // First-month-free conversion: this is the SECOND term. Flip the redemption
244	      // anchored to this subscription to renewed (idempotent, same tx as the money).
245	      await markPromoRenewed(tx, sub.id);
246	    });
247	    return true;
248	  } catch (e) {
249	    if (e instanceof AlreadyHandledError) {
250	      console.log(`${LOG} email ${sub.id} already renewed by another pass — skipping`);
251	      return false;
252	    }
253	    if (e instanceof InsufficientBalanceError) {
254	      // Balance was spent between the read and the debit; the warn/grace path
255	      // picks it up on the next sweep.
256	      console.log(`${LOG} email ${sub.id} lost the race for funds — retrying next sweep`);
257	      return false;
258	    }
259	    throw e;
260	  }
261	}
262	
263	/** Suspend an unpaid subscription past grace. Mailboxes are never deleted. */
264	async function suspendEmail(
265	  sub: { id: string; userId: string; domainName: string; expiresAt: Date | null },
266	  priceCents: number
267	) {
268	  const suspended = await db.emailSubscription.updateMany({
269	    where: { id: sub.id, status: "ACTIVE" },
270	    data: { status: "SUSPENDED" },
271	  });
272	  if (suspended.count === 0) return; // another pass got there first
273	
274	  await db.auditLog.create({
275	    data: {
276	      userId: sub.userId,
277	      action: "billing.suspended_unpaid",
278	      detail: `email ${sub.id} ${sub.domainName}`,
279	    },
280	  });
281	  await notify(
282	    sub.userId,
283	    `${sub.domainName} email suspended — payment overdue`,
284	    `Mail delivery is paused. Your mailboxes and their contents are kept — top up ${money(priceCents)} and renew from your email page to restore delivery.`,
285	    EMAIL_HREF
286	  );
287	  console.log(`${LOG} suspended unpaid email subscription ${sub.id} (${sub.domainName})`);
288	}
289	
290	/** Renew / warn / suspend every ACTIVE subscription that is past its expiry. */
291	async function emailDueSweep(now: Date) {
292	  const due = await db.emailSubscription.findMany({
293	    where: { status: "ACTIVE", expiresAt: { not: null, lt: now } },
294	    include: { emailPlan: true, user: true },
295	  });
296	  const liveAnnual = await annualDiscountPct();
297	
298	  for (const sub of due) {
299	    await step(`email renewal ${sub.id}`, async () => {
300	      if (!sub.expiresAt) return;
301	      const priceCents = emailRenewalPrice(sub, liveAnnual);
302	      const action = renewalDecision({
303	        expiresAt: sub.expiresAt,
304	        now,
305	        autoRenew: sub.autoRenew,
306	        balanceCents: sub.user.balanceCents,
307	        priceCents,
308	      });
309	
310	      if (action === "renew") {
311	        // Advance by the sub's own term, so an annual sub renews for another year.
312	        const newExpiry = nextExpiry(sub.expiresAt, now, subscriptionTermMonths(sub));
313	        const renewed = await chargeEmailRenewal(sub, sub.emailPlan.name, priceCents, newExpiry);
314	        if (!renewed) return;
315	        await notify(
316	          sub.userId,
317	          `${sub.domainName} email renewed`,
318	          `Charged ${money(priceCents)} for ${sub.emailPlan.name}. Next renewal ${ymd(newExpiry)}.`,
319	          EMAIL_HREF
320	        );
321	        console.log(`${LOG} renewed email ${sub.domainName} until ${newExpiry.toISOString()}`);
322	        return;
323	      }
324	
325	      if (action === "enforce") {
326	        await suspendEmail(sub, priceCents);
327	        return;
328	      }
329	
330	      // Still inside the grace window — keep it delivering, nag once.
331	      await notifyOnce(
332	        now,
333	        sub.userId,
334	        sub.domainName,
335	        "email renewal failed",
336	        `${sub.domainName} email renewal failed — top up to keep it active`,
337	        sub.autoRenew
338	          ? `We couldn't charge ${money(priceCents)} (balance ${money(sub.user.balanceCents)}). Mail keeps flowing until ${ymd(graceEndsAt(sub.expiresAt, PRODUCT_GRACE_DAYS))}, then the subscription is suspended. Your mailboxes are not deleted.`
339	          : `Auto-renew is off and this subscription expired. Renew before ${ymd(graceEndsAt(sub.expiresAt, PRODUCT_GRACE_DAYS))} to avoid suspension. Your mailboxes are not deleted.`,
340	        EMAIL_HREF
341	      );
342	    });
343	  }
344	}
345	
346	// ---------------------------------------------------------------------------
347	// Shared hosting accounts (monthly)
348	// ---------------------------------------------------------------------------
349	
350	const HOSTING_HREF = "/dashboard/hosting";
351	
352	/** Charge one hosting renewal, CAS-guarded on expiresAt (double-charge guard). */
353	async function chargeHostingRenewal(
354	  acct: { id: string; userId: string; primaryDomain: string; expiresAt: Date | null },
355	  planName: string,
356	  priceCents: number,
357	  newExpiry: Date,
358	): Promise<boolean> {
359	  try {
360	    await db.$transaction(async (tx) => {
361	      const advanced = await tx.hostingAccount.updateMany({
362	        where: { id: acct.id, status: "ACTIVE", expiresAt: acct.expiresAt },
363	        data: { expiresAt: newExpiry },
364	      });
365	      if (advanced.count === 0) throw new AlreadyHandledError(`hosting ${acct.id}`);
366	      if (priceCents > 0) {
367	        await debitWallet(tx, acct.userId, priceCents);
368	        await tx.walletTransaction.create({
369	          data: { userId: acct.userId, amountCents: -priceCents, description: `Web Hosting renewal: ${planName} for ${acct.primaryDomain}` },
370	        });
371	        await tx.invoice.create({
372	          data: invoiceCreateData({
373	            userId: acct.userId,
374	            description: `Web Hosting renewal: ${planName} for ${acct.primaryDomain}`,
375	            status: "PAID",
376	            period: { start: acct.expiresAt, end: newExpiry },
377	            lineItems: [{ description: `${planName} — ${acct.primaryDomain}`, qty: 1, unitCents: priceCents, amountCents: priceCents }],
378	          }),
379	        });
380	      }
381	      await tx.auditLog.create({
382	        data: { userId: acct.userId, action: "billing.renewed", detail: `hosting ${acct.id} ${acct.primaryDomain} ${money(priceCents)} -> ${ymd(newExpiry)}` },
383	      });
384	      // First-month-free conversion: this is the SECOND term. Flip the redemption
385	      // anchored to this account to renewed (idempotent, same tx as the money).
386	      await markPromoRenewed(tx, acct.id);
387	    });
388	    return true;
389	  } catch (e) {
390	    if (e instanceof AlreadyHandledError) return false;
391	    if (e instanceof InsufficientBalanceError) return false;
392	    throw e;
393	  }
394	}
395	
396	/** Suspend an unpaid hosting account past grace. Files are never deleted. */
397	async function suspendHosting(acct: { id: string; userId: string; primaryDomain: string; expiresAt: Date | null }) {
398	  const suspended = await db.hostingAccount.updateMany({
399	    where: { id: acct.id, status: "ACTIVE", expiresAt: acct.expiresAt },
400	    data: { status: "SUSPENDED", suspendedNote: "Payment overdue" },
401	  });
402	  if (suspended.count === 0) return;
403	  await db.auditLog.create({ data: { userId: acct.userId, action: "billing.suspended_unpaid", detail: `hosting ${acct.id} ${acct.primaryDomain}` } });
404	  await notify(acct.userId, `${acct.primaryDomain} hosting suspended — payment overdue`, `Top up your wallet and we'll restore it. Your files and databases are kept.`, HOSTING_HREF);
405	  console.log(`${LOG} suspended unpaid hosting account ${acct.id} (${acct.primaryDomain})`);
406	}
407	
408	/**
409	 * When the wallet can't cover a hosting renewal but the customer has a saved card,
410	 * top the wallet up from the card for the shortfall — the SAME "card funds the
411	 * wallet, wallet pays the bill" model worker/billing.ts uses for VPS renewals, and
412	 * the answer to the checkout gate that accepts a card-on-file for a $0 first month.
413	 *
414	 * Reuses the audited off-session primitives verbatim: `chargeSavedCardOffSession`
415	 * (two idempotency guards — a permanent per-period marker + Stripe's 24h key) and
416	 * `creditOffSessionCharge` (UNIQUE(paymentIntentId) so a replay credits once). On
417	 * any failure the wallet is left untouched and the caller falls through to the
418	 * existing wallet-only grace/suspend path — a card wobble never suspends anyone
419	 * early. Returns the wallet balance to price the renewal decision against.
420	 */
421	async function topUpHostingFromCard(
422	  acct: { id: string; expiresAt: Date | null; primaryDomain: string; user: { id: string; email: string; name: string | null; balanceCents: number; stripeCustomerId: string | null; stripePaymentMethodId: string | null; cardBrand: string | null; cardLast4: string | null; cardExpMonth: number | null; cardExpYear: number | null } },
423	  priceCents: number,
424	): Promise<number> {
425	  const user = acct.user;
426	  if (canAfford(user.balanceCents, priceCents)) return user.balanceCents;
427	  if (!acct.expiresAt || !hasChargeableCard(user)) return user.balanceCents;
428	  // Wallet credit first, card for the remainder — identical split to checkout and
429	  // the VPS sweep, so the card is only ever asked for what the wallet can't cover.
430	  const split = walletSplit({ dueCents: priceCents, balanceCents: user.balanceCents, useWallet: true });
431	  if (split.cardCents <= 0) return user.balanceCents;
432	  const marker = renewalChargeMarker(acct.id, acct.expiresAt);
433	  const idempotencyKey = `nxeon_hostrenew_${acct.id}_${acct.expiresAt.getTime()}_${split.cardCents}`;
434	  const cardLabel = cardDisplayLabel({ brand: user.cardBrand, last4: user.cardLast4, expMonth: user.cardExpMonth, expYear: user.cardExpYear }) ?? "your saved card";
435	  const result = await chargeSavedCardOffSession({
436	    user,
437	    amountCents: split.cardCents,
438	    description: `Web Hosting renewal: ${acct.primaryDomain}`,
439	    marker,
440	    idempotencyKey,
441	    metadata: { nxeonHostingAccountId: acct.id, nxeonPeriodStart: acct.expiresAt.toISOString(), nxeonKind: "hosting_renewal" },
442	  });
443	  if (!result.ok) return user.balanceCents; // decline / 3DS / transient — fall through to grace
444	  // Credit the wallet with exactly what Stripe took (a replay credits once).
445	  await creditOffSessionCharge({
446	    userId: user.id,
447	    amountCents: result.amountCents,
448	    description: `Card payment for ${acct.primaryDomain} hosting renewal (${cardLabel})`,
449	    paymentIntentId: result.paymentIntentId,
450	  });
451	  return user.balanceCents + result.amountCents;
452	}
453	
454	async function hostingDueSweep(now: Date) {
455	  const due = await db.hostingAccount.findMany({
456	    where: { status: "ACTIVE", expiresAt: { not: null, lt: now } },
457	    include: { plan: true, user: true },
458	  });
459	  const liveAnnual = await annualDiscountPct();
460	  const perGbCents = await extraDiskPerGbCents();
461	  for (const acct of due) {
462	    await step(`hosting renewal ${acct.id}`, async () => {
463	      if (!acct.expiresAt) return;
464	      const priceCents = hostingRenewalPrice(acct, liveAnnual, perGbCents);
465	      // Fund the wallet from a saved card if it's short (the wallet still pays the
466	      // renewal below). Best-effort — a failure leaves the wallet as-is.
467	      const balanceCents = await topUpHostingFromCard(acct, priceCents);
468	      const action = renewalDecision({ expiresAt: acct.expiresAt, now, autoRenew: true, balanceCents, priceCents });
469	      if (action === "renew") {
470	        // Advance by the account's own term, so an annual account renews annually.
471	        const newExpiry = nextExpiry(acct.expiresAt, now, subscriptionTermMonths(acct));
472	        const renewed = await chargeHostingRenewal(acct, acct.plan.name, priceCents, newExpiry);
473	        if (!renewed) return;
474	        await notify(acct.userId, `${acct.primaryDomain} hosting renewed`, `Charged ${money(priceCents)} for ${acct.plan.name}. Next renewal ${ymd(newExpiry)}.`, HOSTING_HREF);
475	        return;
476	      }
477	      if (action === "enforce") {
478	        await suspendHosting(acct);
479	        return;
480	      }
481	      await notifyOnce(
482	        now, acct.userId, acct.primaryDomain, "hosting renewal failed",
483	        `${acct.primaryDomain} hosting renewal failed — top up to keep it active`,
484	        `We couldn't charge ${money(priceCents)} (balance ${money(acct.user.balanceCents)}). Your site stays up until ${ymd(graceEndsAt(acct.expiresAt, PRODUCT_GRACE_DAYS))}, then it is suspended. Your files are not deleted.`,
485	        HOSTING_HREF,
486	      );
487	    });
488	  }
489	}
