491	// ---------------------------------------------------------------------------
492	// Block storage volumes
493	// ---------------------------------------------------------------------------
494	
495	const VOLUME_HREF = "/dashboard/volumes";
496	
497	/** Volume states that are live and therefore billable. */
498	const BILLABLE_VOLUME_STATUSES = ["PENDING", "ATTACHED", "DETACHED"];
499	
500	/** Heads-up for volumes expiring soon that the wallet can't cover. */
501	async function volumeUpcomingWarnings(now: Date) {
502	  const soon = new Date(now.getTime() + PRODUCT_WARN_DAYS * 86400_000);
503	  const upcoming = await db.volume.findMany({
504	    where: { status: { in: BILLABLE_VOLUME_STATUSES }, expiresAt: { gt: now, lt: soon } },
505	    include: { user: true },
506	  });
507	
508	  for (const volume of upcoming) {
509	    await step(`volume warn ${volume.id}`, async () => {
510	      const priceCents = volumeRenewalCents(volume);
511	      if (canAfford(volume.user.balanceCents, priceCents)) return;
512	      await notifyOnce(
513	        now,
514	        volume.userId,
515	        volume.name,
516	        "volume renews soon",
517	        `Volume "${volume.name}" renews soon — action needed`,
518	        `Renewal is ${money(priceCents)}/mo but your balance is ${money(volume.user.balanceCents)}. Top up before ${ymd(volume.expiresAt!)} — an unpaid volume is detached from its server (your data is kept).`,
519	        VOLUME_HREF
520	      );
521	    });
522	  }
523	}
524	
525	/**
526	 * Charge + extend one volume atomically. Same compare-and-swap on `expiresAt`
527	 * as the email path, so re-running the sweep can never bill a second month.
528	 */
529	async function chargeVolumeRenewal(
530	  volume: { id: string; userId: string; name: string; sizeGB: number; expiresAt: Date | null; status: string },
531	  priceCents: number,
532	  newExpiry: Date
533	): Promise<boolean> {
534	  try {
535	    await db.$transaction(async (tx) => {
536	      const advanced = await tx.volume.updateMany({
537	        where: { id: volume.id, status: { in: BILLABLE_VOLUME_STATUSES }, expiresAt: volume.expiresAt },
538	        data: { expiresAt: newExpiry },
539	      });
540	      if (advanced.count === 0) throw new AlreadyHandledError(`volume ${volume.id}`);
541	
542	      if (priceCents > 0) {
543	        await debitWallet(tx, volume.userId, priceCents);
544	        await tx.walletTransaction.create({
545	          data: {
546	            userId: volume.userId,
547	            amountCents: -priceCents,
548	            description: `Block storage renewal: ${volume.name} (${volume.sizeGB} GB)`,
549	          },
550	        });
551	        // PAID invoice, inside the CAS-guarded tx — a repeated sweep rolls back.
552	        await tx.invoice.create({
553	          data: invoiceCreateData({
554	            userId: volume.userId,
555	            description: `Block storage renewal: ${volume.name} (${volume.sizeGB} GB)`,
556	            status: "PAID",
557	            period: { start: volume.expiresAt, end: newExpiry },
558	            lineItems: [
559	              { description: `Block storage — ${volume.name} (${volume.sizeGB} GB)`, qty: 1, unitCents: priceCents, amountCents: priceCents },
560	            ],
561	          }),
562	        });
563	      }
564	      await tx.auditLog.create({
565	        data: {
566	          userId: volume.userId,
567	          action: "billing.renewed",
568	          detail: `volume ${volume.id} ${volume.name} ${money(priceCents)} -> ${ymd(newExpiry)}`,
569	        },
570	      });
571	    });
572	    return true;
573	  } catch (e) {
574	    if (e instanceof AlreadyHandledError) {
575	      console.log(`${LOG} volume ${volume.id} already renewed by another pass — skipping`);
576	      return false;
577	    }
578	    if (e instanceof InsufficientBalanceError) {
579	      console.log(`${LOG} volume ${volume.id} lost the race for funds — retrying next sweep`);
580	      return false;
581	    }
582	    throw e;
583	  }
584	}
