586	/**
587	 * Enforcement for an unpaid volume past grace: detach only, never destroy.
588	 * An ATTACHED volume is flipped to DETACHED and a VOLUME_DETACH job is queued
589	 * (both in one transaction, so we never mark it detached without doing it).
590	 * The underlying disk — and every byte on it — is left intact.
591	 */
592	async function detachUnpaidVolume(
593	  volume: {
594	    id: string;
595	    userId: string;
596	    name: string;
597	    serverId: string | null;
598	    status: string;
599	    expiresAt: Date | null;
600	  },
601	  priceCents: number,
602	  now: Date
603	) {
604	  if (volume.status !== "ATTACHED") {
605	    // Nothing to detach (PENDING / already DETACHED) — just keep nagging.
606	    await notifyOnce(
607	      now,
608	      volume.userId,
609	      volume.name,
610	      "volume unpaid",
611	      `Volume "${volume.name}" is unpaid`,
612	      `This volume is overdue by ${money(priceCents)}/mo. Your data is retained, but the volume may be removed if it stays unpaid past ${ymd(reclaimAt(volume.expiresAt!))}. Top up to keep it.`,
613	      VOLUME_HREF
614	    );
615	    return;
616	  }
617	
618	  // Respect the one-in-flight-job guard so we don't collide with a user or
619	  // worker operation already running on that server; retry on the next sweep.
620	  if (volume.serverId) {
621	    const busy = await db.job.count({
622	      where: { serverId: volume.serverId, status: { in: ["QUEUED", "RUNNING"] } },
623	    });
624	    if (busy > 0) return;
625	  }
626	
627	  try {
628	    await db.$transaction(async (tx) => {
629	      const flipped = await tx.volume.updateMany({
630	        where: { id: volume.id, status: "ATTACHED" },
631	        data: { status: "DETACHED" },
632	      });
633	      if (flipped.count === 0) throw new AlreadyHandledError(`volume ${volume.id}`);
634	      await tx.job.create({
635	        data: { type: "VOLUME_DETACH", serverId: volume.serverId, payload: { volumeId: volume.id } },
636	      });
637	      await tx.auditLog.create({
638	        data: {
639	          userId: volume.userId,
640	          action: "billing.volume_detached_unpaid",
641	          detail: `volume ${volume.id} ${volume.name}`,
642	        },
643	      });
644	    });
645	  } catch (e) {
646	    if (e instanceof AlreadyHandledError) return;
647	    throw e;
648	  }
649	
650	  await notify(
651	    volume.userId,
652	    `Volume "${volume.name}" detached — payment overdue`,
653	    `We couldn't collect ${money(priceCents)} for this volume, so it was detached from your server. Nothing was deleted: all data on the volume is retained and re-attaches exactly as it was once you top up and renew. If it stays unpaid past ${ymd(reclaimAt(volume.expiresAt!))} the volume may be removed.`,
654	    VOLUME_HREF
655	  );
656	  console.log(`${LOG} detached unpaid volume ${volume.id} (${volume.name})`);
657	}
658	
659	/** Renew / warn / detach every billable volume that is past its expiry. */
660	async function volumeDueSweep(now: Date) {
661	  const due = await db.volume.findMany({
662	    where: { status: { in: BILLABLE_VOLUME_STATUSES }, expiresAt: { not: null, lt: now } },
663	    include: { user: true },
664	  });
665	
666	  for (const volume of due) {
667	    await step(`volume renewal ${volume.id}`, async () => {
668	      if (!volume.expiresAt) return;
669	      const priceCents = volumeRenewalCents(volume);
670	      const action = renewalDecision({
671	        expiresAt: volume.expiresAt,
672	        now,
673	        autoRenew: true, // volumes have no opt-out; they renew until deleted
674	        balanceCents: volume.user.balanceCents,
675	        priceCents,
676	      });
677	
678	      if (action === "renew") {
679	        const newExpiry = nextExpiry(volume.expiresAt, now, VOLUME_TERM_MONTHS);
680	        const renewed = await chargeVolumeRenewal(volume, priceCents, newExpiry);
681	        if (!renewed) return;
682	        await notify(
683	          volume.userId,
684	          `Volume "${volume.name}" renewed`,
685	          `Charged ${money(priceCents)} for ${volume.sizeGB} GB. Next renewal ${ymd(newExpiry)}.`,
686	          VOLUME_HREF
687	        );
688	        console.log(`${LOG} renewed volume ${volume.id} until ${newExpiry.toISOString()}`);
689	        return;
690	      }
691	
692	      if (action === "enforce") {
693	        await detachUnpaidVolume(volume, priceCents, now);
694	        return;
695	      }
696	
697	      // Inside grace — the volume stays attached and usable; nag once.
698	      await notifyOnce(
699	        now,
700	        volume.userId,
701	        volume.name,
702	        "volume renewal failed",
703	        `Volume "${volume.name}" renewal failed — top up to keep it attached`,
704	        `We couldn't charge ${money(priceCents)} (balance ${money(volume.user.balanceCents)}). The volume stays attached until ${ymd(graceEndsAt(volume.expiresAt, PRODUCT_GRACE_DAYS))}, then it is detached from your server. Your data is never deleted automatically.`,
705	        VOLUME_HREF
706	      );
707	    });
708	  }
709	}
710	
711	// ---------------------------------------------------------------------------
712	
713	/**
714	 * Renewal sweep for the add-on products. Safe to call as often as you like:
715	 * each phase only acts on rows whose `expiresAt` is genuinely in the past, and
716	 * every charge advances `expiresAt` in the same transaction, so repeated runs
717	 * are no-ops rather than repeat charges.
718	 *
719	 * Wire into the worker loop next to `billingSweep()` (see worker/index.ts).
720	 */
721	export async function productRenewalSweep(): Promise<void> {
722	  const now = new Date();
723	  await phase("email upcoming warnings", () => emailUpcomingWarnings(now));
724	  await phase("email renewals", () => emailDueSweep(now));
725	  await phase("volume upcoming warnings", () => volumeUpcomingWarnings(now));
726	  await phase("volume renewals", () => volumeDueSweep(now));
727	  await phase("hosting renewals", () => hostingDueSweep(now));
728	}
