1	// Spend caps + monthly-budget alerts (Finding 3). Plain server module.
2	//
3	// "Spend" here means MONEY ACTUALLY CHARGED FOR SERVICES this calendar month: the
4	// sum of the negative `WalletTransaction` amounts (orders, renewals, resizes). Wallet
5	// TOP-UPS are positive credits and are never counted — adding money to the wallet is
6	// not spending it, and a hard cap must never block a customer topping up to pay a
7	// bill. Refund credits are likewise positive and excluded.
8	//
9	// Two features, both opt-in and both defaulting OFF so an account that has not
10	// configured them behaves exactly as before:
11	//   • a SOFT monthly budget that emails once when spend first crosses it, and
12	//   • a HARD monthly cap that REFUSES a new paid order / manual wallet renewal that
13	//     would push spend past it.
14	//
15	// The hard cap is enforced at the discretionary spend paths (placeOrder, renewNow),
16	// NOT in the automatic auto-renew sweep: a standing auto-renew instruction must not
17	// silently lapse and destroy an existing server because of a budget number.
18	
19	import { db } from "./db";
20	import type { Prisma } from "@prisma/client";
21	
22	export class SpendCapError extends Error {
23	  constructor(message: string) {
24	    super(message);
25	    this.name = "SpendCapError";
26	  }
27	}
28	
29	/** "YYYY-MM" for a date in UTC — the bucket both spend-to-date and the alert use. */
30	export function monthKey(d: Date = new Date()): string {
31	  return `${d.getUTCFullYear()}-${String(d.getUTCMonth() + 1).padStart(2, "0")}`;
32	}
33	
34	/** First instant of the current UTC calendar month. */
35	export function startOfMonth(d: Date = new Date()): Date {
36	  return new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), 1));
37	}
38	
39	/**
40	 * Service spend (in cents, positive) for this account so far this calendar month:
41	 * the magnitude of every negative wallet transaction since the month began. Runs on
42	 * the passed transaction client when given one so a caller can read it inside the
43	 * same tx that is about to debit.
44	 */
45	export async function monthSpendCents(
46	  userId: string,
47	  client: Prisma.TransactionClient | typeof db = db,
48	  now: Date = new Date(),
49	): Promise<number> {
50	  const agg = await client.walletTransaction.aggregate({
51	    where: { userId, amountCents: { lt: 0 }, createdAt: { gte: startOfMonth(now) } },
52	    _sum: { amountCents: true },
53	  });
54	  return Math.abs(agg._sum.amountCents ?? 0);
55	}
56	
57	/**
58	 * Refuse a new discretionary charge of `addCents` when the account has a hard cap
59	 * enabled and this charge would push month-to-date spend past it. No-op when the cap
60	 * is disabled or unset. Throws SpendCapError (a clear, customer-facing message) so
61	 * the order/renew action can surface it verbatim.
62	 *
63	 * Advisory-but-safe: the cap is the customer's OWN limit, not a security boundary, so
64	 * a read-then-charge check is acceptable; it is called immediately before the debit.
65	 */
66	export async function assertSpendCap(
67	  user: { id: string; spendCapEnabled?: boolean; hardCapCents?: number | null },
68	  addCents: number,
69	  client: Prisma.TransactionClient | typeof db = db,
70	): Promise<void> {
71	  if (!user.spendCapEnabled || user.hardCapCents == null || addCents <= 0) return;
72	  const cap = user.hardCapCents;
73	  const spent = await monthSpendCents(user.id, client);
74	  if (spent + addCents > cap) {
75	    const remain = Math.max(0, cap - spent);
76	    throw new SpendCapError(
77	      `This purchase ($${(addCents / 100).toFixed(2)}) would exceed your monthly spend cap of ` +
78	        `$${(cap / 100).toFixed(2)} — you have $${(remain / 100).toFixed(2)} left this month. ` +
79	        `Raise or turn off the cap in Billing to continue.`,
80	    );
81	  }
82	}
83	
84	/**
85	 * After a charge lands, email the customer at most ONCE per calendar month the first
86	 * time their month-to-date spend crosses their soft budget. Best-effort and
87	 * idempotent via `budgetAlertedPeriod`; never throws into the charge path.
88	 */
89	export async function maybeAlertBudget(userId: string): Promise<void> {
90	  try {
91	    const user = await db.user.findUnique({ where: { id: userId } });
92	    if (!user || !user.budgetAlertEnabled || user.monthlyBudgetCents == null) return;
93	    const period = monthKey();
94	    if (user.budgetAlertedPeriod === period) return; // already told them this month
95	    const spent = await monthSpendCents(userId);
96	    if (spent < user.monthlyBudgetCents) return;
97	    // Stamp FIRST (idempotency): only the writer that flips the period from "not this
98	    // month" sends, so two concurrent charges can't both email.
99	    const stamped = await db.user.updateMany({
100	      where: { id: userId, budgetAlertedPeriod: user.budgetAlertedPeriod ?? null },
101	      data: { budgetAlertedPeriod: period },
102	    });
103	    if (stamped.count !== 1) return;
104	    await db.notification.create({
105	      data: {
106	        userId,
107	        title: `You've reached your monthly budget of $${(user.monthlyBudgetCents / 100).toFixed(2)}`,
108	        body: `Your Nxeon service spend this month is $${(spent / 100).toFixed(2)}. This is a heads-up only — nothing is blocked. Set a hard spend cap in Billing if you want new purchases stopped automatically.`,
109	        href: "/dashboard/billing",
110	      },
111	    });
112	    try {
113	      const { sendMail, emails } = await import("./mailer");
114	      const tpl = (emails as any).budgetAlert
115	        ? (emails as any).budgetAlert(user.monthlyBudgetCents, spent)
116	        : {
117	            subject: `Nxeon: monthly budget of $${(user.monthlyBudgetCents / 100).toFixed(2)} reached`,
118	            html: `<p>Your Nxeon service spend this month is <b>$${(spent / 100).toFixed(2)}</b>, which has reached the monthly budget of $${(user.monthlyBudgetCents / 100).toFixed(2)} you set.</p><p>This is a notification only — nothing has been blocked. You can review spend and set a hard cap in your <a href="/dashboard/billing">billing settings</a>.</p>`,
119	          };
120	      await sendMail({ to: user.email, subject: tpl.subject, html: tpl.html, userId, kind: "invoice" });
121	    } catch {
122	      /* best-effort mail */
123	    }
124	  } catch {
125	    /* never break a charge because an alert failed */
126	  }
127	}
