18	/**
19	 * One customer's whole estate, normalised into a single list.
20	 *
21	 * The four products live in genuinely different tables — a VPS and a game
22	 * server are both `Server` rows told apart by `gamePlanId`, shared hosting is
23	 * a `HostingAccount`, and the free Minecraft tier is its own
24	 * `FreeMinecraftServer` — so this is the one place that flattens them into a
25	 * shape a single list can render. Everything below is read from the record;
26	 * nothing is inferred where the data doesn't exist (hosting has no region
27	 * column, so its location is geo-resolved from the node's real public IP the
28	 * same way the primary node's location was confirmed, and is left blank when
29	 * that lookup can't answer).
30	 */
31	export type ServiceKind = "vps" | "game" | "hosting" | "free";
32	
33	/** The five buckets the page's stat row and status pills speak in. */
34	export type ServiceStatus = "running" | "pending" | "stopped" | "suspended" | "error" | "cancelled";
35	
36	export type ServiceRow = {
37	  id: string;
38	  kind: ServiceKind;
39	  /** What the customer named it (or the domain, for hosting). */
40	  name: string;
41	  /** Where "Manage" goes. */
42	  href: string;
43	  typeLabel: string;
44	  /** The address a customer actually connects on. See `connectAddress`. */
45	  address: string | null;
46	  /** What that address IS, so the row can label it rather than guess. */
47	  addressLabel: "IP address" | "Connect" | "Website" | null;
48	  /** Second line under the name — plan/specs. */
49	  specs: string | null;
50	  status: ServiceStatus;
51	  statusLabel: string;
52	  location: { label: string; country: string } | null;
53	  renewalIso: string | null;
54	  /** Per-term price in cents; null when nothing is charged (free tier). */
55	  renewalCents: number | null;
56	  /** Billing term in months, so "/mo" vs "/yr" is honest. */
57	  termMonths: number;
58	  /** Game family id, for the box-art thumbnail. */
59	  gameFamily: string | null;
60	  /** Hosting only — the site to preview. */
61	  domain: string | null;
62	  createdAtIso: string;
63	
64	  /* ── card preview art ───────────────────────────────────────────────────
65	     Every card leads with a picture. Where it comes from depends on the
66	     product, and the rule is the same one the brief sets out: show the real
67	     thing if there is one, otherwise the stock plate for that product. */
68	
69	  /** The image the card leads with. Never null — there is always a fallback. */
70	  previewSrc: string;
71	  /** Which of the three sources `previewSrc` came from — the card badges it. */
72	  previewSource: "game-art" | "customer" | "stock";
73	  /**
74	   * Hosting only: the live site can be framed over the stock plate, so a plan
75	   * that is actually serving something shows THAT instead of the plate. There
76	   * is no screenshot service behind this — it is the customer's own site or
77	   * the plate, never a stand-in picture of some other website.
78	   */
79	  siteToFrame: string | null;
80	  /** VPS rows let the customer replace the stock plate with their own image. */
81	  canSetPreview: boolean;
82	  /**
83	   * VPS only: what it is actually running. Every VPS on the stock plate would
84	   * otherwise be the same picture, and the OS is the one thing that genuinely
85	   * tells them apart at a glance.
86	   */
87	  os: { family: string; name: string } | null;
88	};
