90	/** Tolerant status mapper: every product spells its states differently, and a
91	 *  new value should degrade to something sane rather than crash a list. */
92	function normalizeStatus(raw: string): { status: ServiceStatus; label: string } {
93	  const s = (raw ?? "").toUpperCase();
94	  if (["RUNNING", "ACTIVE", "ONLINE"].includes(s)) return { status: "running", label: "Running" };
95	  // The free tier's container states: READY means the container exists —
96	  // mc-router owns whether it is awake right now, and this list deliberately
97	  // doesn't claim to know that, so it says Ready rather than Running.
98	  if (s === "READY") return { status: "running", label: "Ready" };
99	  if (["PENDING", "PROVISIONING", "CREATING", "REINSTALLING", "STARTING"].includes(s)) {
100	    return { status: "pending", label: s === "REINSTALLING" ? "Reinstalling" : "Pending" };
101	  }
102	  if (["STOPPED", "SLEEPING", "OFFLINE"].includes(s)) {
103	    return { status: "stopped", label: s === "SLEEPING" ? "Asleep" : "Stopped" };
104	  }
105	  if (["SUSPENDED"].includes(s)) return { status: "suspended", label: "Suspended" };
106	  if (["DELETING", "DELETED", "CANCELLED", "CANCELED", "TERMINATED", "EXPIRED"].includes(s)) {
107	    return { status: "cancelled", label: s === "DELETING" ? "Deleting" : "Cancelled" };
108	  }
109	  if (["ERROR", "FAILED"].includes(s)) return { status: "error", label: "Failed" };
110	  return { status: "pending", label: raw ? raw.charAt(0) + raw.slice(1).toLowerCase() : "Unknown" };
111	}
112	
113	function regionLocation(region: string | null | undefined) {
114	  if (!region) return null;
115	  const label = REGION_LABELS[region];
116	  if (!label) return null;
117	  return { label, country: REGION_COUNTRY[region] ?? "" };
118	}
