122	/** Stock plates, for a service with nothing of its own to show yet. */
123	const STOCK_PREVIEW = {
124	  vps: "/nx/preview/vps.webp",
125	  hosting: "/nx/preview/hosting.webp",
126	} as const;
127	
128	/** Landscape key art for a game family, which every family in the catalogue has. */
129	function gameHeroArt(family: string | null): string | null {
130	  const slug = family ? GAME_ART_SLUG[family as GameFamily]?.hero : null;
131	  return slug ? `/games/art/${slug}_hero.jpg` : null;
132	}
133	
134	/**
135	 * Where a Server row's card image comes from, in priority order: the image the
136	 * customer set, then the game's own key art, then the stock rack plate. The
137	 * `v` stamp is the preview's updatedAt, so replacing an image busts the cache
138	 * without making the route itself uncacheable.
139	 */
140	function serverPreview(
141	  id: string, isGame: boolean, family: string | null, previewStamp: Date | null,
142	): Pick<ServiceRow, "previewSrc" | "previewSource" | "siteToFrame" | "canSetPreview"> {
143	  if (previewStamp) {
144	    return {
145	      previewSrc: `/api/services/preview/${id}?v=${previewStamp.getTime()}`,
146	      previewSource: "customer",
147	      siteToFrame: null,
148	      canSetPreview: true,
149	    };
150	  }
151	  const art = isGame ? gameHeroArt(family) : null;
152	  return {
153	    previewSrc: art ?? STOCK_PREVIEW.vps,
154	    previewSource: art ? "game-art" : "stock",
155	    siteToFrame: null,
156	    // Game servers lead with their own key art, which is better than anything a
157	    // customer would upload — the swap is offered on VPS rows only.
158	    canSetPreview: !isGame,
159	  };
160	}
