163	export async function listServices(userId: string): Promise<ServiceRow[]> {
164	  const user = await db.user.findUnique({ where: { id: userId } });
165	  if (!user) return [];
166	
167	  // The play-subdomain base is an admin SETTING shared by free and paid game
168	  // servers, not a constant — reading it keeps the connect address honest if
169	  // the owner ever moves it off play.nxeon.cloud.
170	  const [servers, hosting, freeMc, gameBase] = await Promise.all([
171	    db.server.findMany({
172	      // NxCloud instances are backed by a Server but sold as their own product,
173	      // so they stay out of this list exactly as they do on /dashboard/servers.
174	      where: { userId, nxcloudInstance: { is: null } },
175	      include: {
176	        plan: true,
177	        gamePlan: true,
178	        osTemplate: true,
179	        // `dedicatedIp` is not decoration here — renewalCharge bills it.
180	        dedicatedIp: { select: { address: true } },
181	        node: { select: { region: true, publicIp: true } },
182	        portForwards: { select: { publicPort: true, guestPort: true } },
183	        // Only the stamp — the bytes are served by their own route, and must
184	        // never be dragged into a list query.
185	        preview: { select: { updatedAt: true } },
186	      },
187	      orderBy: { createdAt: "desc" },
188	    }),
189	    db.hostingAccount.findMany({
190	      where: { userId },
191	      include: { plan: true, node: { select: { publicIp: true, name: true } } },
192	      orderBy: { createdAt: "desc" },
193	    }),
194	    db.freeMinecraftServer.findUnique({ where: { userId } }),
195	    gameSubdomainBase(),
196	  ]);
197	
198	  /* What a server ACTUALLY renews at.
199	   *
200	   * `plan.priceCents` is not that number: it ignores the term (an annual server
201	   * renews at 12x less the frozen annual discount), it ignores every add-on the
202	   * customer really is billed for each cycle (dedicated IP, extra root disk,
203	   * paid backup retention), and for a game server it is the wrong plan
204	   * entirely — a game row carries BOTH a base planId and a gamePlanId and is
205	   * sold at the game plan's flat price. lib/renewal-quote.ts records what
206	   * happened the last two times someone wrote that second formula. So this
207	   * prices through `renewalCharge`, the same function worker/billing.ts, the
208	   * saved-card path and the Renew now button all CHARGE through. */
209	  const paid = servers.filter((s) => !s.isFree);
210	  const taxRatePercent = (await taxContextForUser(user)).ratePercent;
211	  const prices = paid.length > 0
212	    ? {
213	        ipMonthlyCents: await dedicatedIpMonthlyCents(),
214	        extraDiskPerGbCents: await extraDiskPerGbCents(),
215	        backupPlusCents: await backupPlusMonthlyCents(),
216	        annualDiscountPct: await annualDiscountPct(),
217	        taxRatePercent,
218	      }
219	    : {
220	        ipMonthlyCents: 0, extraDiskPerGbCents: 0, backupPlusCents: 0,
221	        annualDiscountPct: DEFAULT_ANNUAL_DISCOUNT_PCT, taxRatePercent,
222	      };
223	
224	  const rows: ServiceRow[] = [];
225	
226	  for (const s of servers) {
227	    const isGame = s.gamePlanId !== null;
228	    const st = normalizeStatus(s.status);
229	    const family = s.gamePlan?.gameFamily ?? s.osTemplate?.family ?? null;
230	    const gameName = family ? GAME_DISPLAY[family as keyof typeof GAME_DISPLAY]?.name ?? family : null;
231	    const charge = renewalCharge(s, prices);
232	    rows.push({
233	      id: s.id,
234	      kind: isGame ? "game" : "vps",
235	      name: s.label || s.hostname,
236	      href: `/dashboard/servers/${s.id}`,
237	      typeLabel: isGame ? gameName ?? "Game Server" : "VPS Server",
238	      ...connectAddress(s, gameBase),
239	      specs: isGame
240	        ? gamePlanSpecs(s.gamePlan?.name, gameName, s.gamePlan?.slots)
241	        : s.plan
242	          ? specLine(s.plan.cpuCores, s.plan.ramMB, s.plan.diskGB, s.plan.storageTier)
243	          : null,
244	      status: st.status,
245	      statusLabel: st.label,
246	      location: regionLocation(s.node?.region),
247	      renewalIso: s.expiresAt ? s.expiresAt.toISOString() : null,
248	      renewalCents: s.isFree ? null : charge.totalCents,
249	      termMonths: s.isFree ? 1 : charge.months,
250	      gameFamily: isGame ? family : null,
251	      domain: null,
252	      createdAtIso: s.createdAt.toISOString(),
253	      ...serverPreview(s.id, isGame, family, s.preview?.updatedAt ?? null),
254	      os: !isGame && s.osTemplate
255	        ? {
256	            family: s.osTemplate.logo || s.osTemplate.family,
257	            // `name` is often already the full "Ubuntu 24.04 LTS", so appending
258	            // `version` unconditionally produced "Ubuntu 24.04 LTS 24.04".
259	            name: s.osTemplate.version && !s.osTemplate.name.includes(s.osTemplate.version)
260	              ? `${s.osTemplate.name} ${s.osTemplate.version}`
261	              : s.osTemplate.name,
262	          }
263	        : null,
264	    });
265	  }
266	
267	  for (const h of hosting) {
268	    const st = normalizeStatus(h.status);
269	    // No region column on HostingNode — resolve the node's real public IP
270	    // instead of inventing a city, and leave it blank if that can't answer.
271	    const geo = geoLocateIp(h.node?.publicIp ?? null);
272	    rows.push({
273	      id: h.id,
274	      kind: "hosting",
275	      name: h.primaryDomain,
276	      href: `/dashboard/hosting/${h.id}`,
277	      typeLabel: "Shared Hosting",
278	      // The name IS the domain here, so repeating it as an address would just
279	      // print the same string twice in the same card.
280	      address: null,
281	      addressLabel: "Website",
282	      specs: [h.plan?.name, `${Math.round(h.diskQuotaMB / 1024)} GB disk`].filter(Boolean).join(" • ") || null,
283	      status: st.status,
284	      statusLabel: st.label,
285	      location: geo?.city ? { label: geo.city, country: (geo.country ?? "").toLowerCase() } : null,
286	      renewalIso: h.expiresAt ? h.expiresAt.toISOString() : null,
287	      renewalCents: h.plan?.priceCents ?? null,
288	      termMonths: h.termMonths ?? 1,
289	      gameFamily: null,
290	      domain: h.primaryDomain,
291	      createdAtIso: h.createdAt.toISOString(),
292	      previewSrc: STOCK_PREVIEW.hosting,
293	      previewSource: "stock",
294	      // Only a plan that is actually live is worth framing — a suspended or
295	      // still-provisioning account would frame an error page.
296	      siteToFrame: st.status === "running" ? h.primaryDomain : null,
297	      canSetPreview: false,
298	      os: null,
299	    });
300	  }
301	
302	  if (freeMc) {
303	    // The free tier's LIVE state needs an SSH round trip to freemc-host, which
304	    // is far too expensive to pay on every render of this list — so the row
305	    // shows the stored state and the live one is fetched on its own page.
306	    const st = normalizeStatus(freeMc.status);
307	    rows.push({
308	      id: freeMc.id,
309	      kind: "free",
310	      name: freeMc.name || `${freeMc.subdomain}`,
311	      href: "/dashboard/free-minecraft",
312	      typeLabel: "Minecraft (Free)",
313	      address: `${freeMc.subdomain}.${gameBase}`,
314	      addressLabel: "Connect",
315	      // The two-axis game type + mode, NOT the deprecated flat `preset` column
316	      // the legacy free-MC cards still read.
317	      specs: [
318	        FREEMC_GAME_TYPES[freeMc.activeGameType]?.label ?? freeMc.activeGameType,
319	        FREEMC_GAME_MODES[freeMc.activeGameMode]?.label ?? freeMc.activeGameMode,
320	      ].join(" • "),
321	      status: st.status,
322	      statusLabel: st.label,
323	      location: null,
324	      renewalIso: null,
325	      renewalCents: null,
326	      termMonths: 1,
327	      gameFamily: "minecraft",
328	      domain: null,
329	      createdAtIso: freeMc.createdAt.toISOString(),
330	      // The free tier's card shows the art for the game type actually loaded on
331	      // it — SkyBlock looks like SkyBlock, not like generic Minecraft.
332	      previewSrc:
333	        FREEMC_GAME_TYPES[freeMc.activeGameType]?.heroImage
334	        ?? gameHeroArt("minecraft")
335	        ?? STOCK_PREVIEW.vps,
336	      previewSource: "game-art",
337	      siteToFrame: null,
338	      canSetPreview: false,
339	      os: null,
340	    });
341	  }
342	
343	  return rows.sort((a, b) => b.createdAtIso.localeCompare(a.createdAtIso));
344	}
